            #jack.client-name = PipeWire
            #jack.connect     = true
            #tunnel.mode      = duplex  # source|sink|duplex
            source.props = {
                #audio.channels = 2
		#midi.ports = 1
                #audio.position = [ FL FR ]
                # extra sink properties
            }
            sink.props = {
                #audio.channels = 2
		#midi.ports = 1
                #audio.position = [ FL FR ]
                # extra sink properties
            }
        }

{
            node.name = "filter-chain-sink"
            node.description = "Filter Chain Sink"
            media.name = "Filter Chain Sink"
            filter.graph = {
                nodes = [
                    {
                        type = lv2
            name = valve_deck_speakers
            plugin = "https://faustlv2.bitbucket.io/valve_boulder_speakers"
            label = valve_boulder_speakers
                    }
                ]
        links = [
        ]
            }
            capture.props = {
                node.name = "filter-chain-sink"
                media.class = Audio/Sink
                audio.channels = 2
                audio.position = [ FL FR ]
                filter.smart = true
                filter.smart.name = filter-chain-sink
                filter.smart.target = { media.class = Audio/Sink, alsa.card_name = "SM8250 LPASS", device.profile.description = "Speaker playback" }
                filter.smart.after = [ filter-chain-spatialize ]
            }
            playback.props = {
                node.name = "filter-chain-playback"
                node.passive = true
                audio.channels = 2
                audio.position = [ FL FR ]
            }
        }

{
            node.description = "Mic EQ"
            media.name =  "Mic EQ"
            filter.graph = {
               nodes = [
                    {
                        type = lv2
                        name = eq
                        plugin = "https://faustlv2.bitbucket.io/valve_deckard_mic"
                        label = valve_deckard_mic
                    }
                    {
                        type = builtin
                        name = mono_mixer
                        label = mixer
                    }
               ]
               links = [
                    { output = "eq:out0" input = "mono_mixer:In 1" }
                    { output = "eq:out1" input = "mono_mixer:In 2" }
               ]
               inputs = [ "eq:in0" "eq:in1" ]
               outputs = [ "mono_mixer:Out" ]
            }
            capture.props = {
                node.name = "eq_capture"
                node.passive = true
                audio.channels = 2
                audio.position = [ FL FR ]
            }
            playback.props = {
                node.name = "eq_source"
                media.class = Audio/Source
                audio.channels = 1
                audio.position = [ MONO ]
                filter.smart = true
                filter.smart.name = filter-chain-eq
                filter.smart.target = { media.class = Audio/Source, alsa.card_name = "SM8250 LPASS", device.profile.description = "Mic" }
                # FIXME: WirePlumber seems to invert this
                filter.smart.after = [ filter-chain-ns filter-chain-ec-source filter-chain-ec-fallback-source ]
                filter.smart.disabled = true
                steamos.mic_filter = true
            }
        }

{
            node.description = "Noise Suppressor"
            media.name =  "Noise Suppressor"
            filter.graph = {
               nodes = [
                    {
                        type = ladspa
                        name = noise_suppressor_mono
                        plugin = /usr/lib/ladspa/audiofilter.so
                        label = noise_suppressor_mono
                        control = {
                           "VAD Threshold (%)" = 23
                           "VAD Grace Period (ms)" = 500
                           "Retroactive VAD Grace (ms)" = 0
                           "NS enable" = 1.0
                           # Set this to 1.0 if steamos.filters.mic-eq is false
                           "EQ enable" = 0.0
                        }
                    }
                    {
                        type = builtin
                        name = stereoL
                        label = copy
                    }
                    {
                        type = builtin
                        name = stereoR
                        label = copy
                    }
               ]
               links = [
                    { output = "noise_suppressor_mono:Output" input = "stereoL:In" }
                    { output = "noise_suppressor_mono:Output" input = "stereoR:In" }
               ]
               outputs = [ "stereoL:Out", "stereoR:Out" ]
            }
            capture.props = {
                node.name = "ns_capture"
                node.passive = true
                audio.channels = 1
                audio.position = [ MONO ]
            }
            playback.props = {
                node.name = "ns_source"
                media.class = Audio/Source
                audio.channels = 2
                audio.position = [ FL FR ]
                filter.smart = true
                filter.smart.name = filter-chain-ns
                filter.smart.target = { media.class = Audio/Source, alsa.card_name = "SM8250 LPASS", device.profile.description = "Mic" }
                # FIXME: WirePlumber seems to invert this
                filter.smart.before = [ filter-chain-eq filter-chain-ec-source filter-chain-ec-fallback-source ]
                filter.smart.disabled = true
                steamos.mic_filter = true
            }
        }
